window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6a64539d888e47e"]={"versions": [{"id": "FIG-a6a64539d888e47e", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Strukturdiagramm / Metamodell-Instanzdarstellung einer VFB-Schnittstellendeklaration (Interface Specification).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Virtual Function Bus (VFB), Versionsstand R3.0.7 / R3.1.5 (Kapitel 8: <em>Mode Management</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Definition der Schnittstelle zur Entkopplung von Mode-Manager-Komponenten (hier dem <code>EcuM</code> – ECU State Manager) und applikativen Software-Komponenten (SWCs). Dient der standardisierten Propagierung von Systemzuständen (z. B. <code>STARTUP</code>, <code>RUN</code>, <code>POST_RUN</code>, <code>SLEEP</code>, <code>SHUTDOWN</code>) über den VFB bzw. die RTE an abhängige SWC-Runnables.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Entität:</strong> <code>EcuMCurrentMode</code></li>\n<li><strong>Stereotyp:</strong> <code>&lt;&lt;SenderReceiverInterface&gt;&gt;</code> (Spezifikationsstandard in AUTOSAR R3.x für modale Kommunikation vor Einführung dedizierter <code>ModeSwitchInterfaces</code>).</li>\n<li><strong>Attribute / Enthaltene Elemente:</strong></li>\n<li><strong>Sektion:</strong> <code>ModeDeclarationGroups:</code></li>\n<li><strong>Element:</strong> <code>currentMode</code> als Instanz bzw. Mode-Prototyp der Modusgruppe.</li>\n<li><strong>Typisierung:</strong> <code>ECUMMode</code> (definiert die zulässige Menge diskreter Zustände/Modes als <code>ModeDeclarationGroup</code>).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Ein <code>SenderReceiverInterface</code> aggregiert in R3.x $0..<em>$ <code>ModeDeclarationGroup</code>-Referenzen parallel oder alternativ zu $0..</em>$ <code>DataElements</code>. Im vorliegenden Beispiel besteht eine 1:1-Bindung (<code>ECUMMode currentMode</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um eine statische Metamodell-Deklaration handelt, greift die daraus resultierende Laufzeitsemantik auf dem VFB:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Sender/Mode Manager:</strong> Der <code>EcuM</code> stellt einen P-Port bereit, der das Interface <code>EcuMCurrentMode</code> typisiert. Bei internem Zustandsübergang wird die Modusänderung an die RTE übergeben.</li>\n<li><strong>Receiver/Mode User:</strong> Applikative SWCs binden über R-Ports an dieses Interface.</li>\n<li><strong>RTE-Ablaufsteuerung:</strong></li>\n<li><strong>Moduswechsel (Mode Transition):</strong> Der Übergang triggert RTE-seitig configurierte <code>ModeSwitchEvents</code>.</li>\n<li><strong>Runnable-Steuerung:</strong> Aktivierung von Transitions-Runnables (<code>on-entry</code>, <code>on-exit</code>) oder bedingte Ausführung periodischer Runnables abhängig vom aktiven Modus.</li>\n<li><strong>Synchronisation:</strong> Ausführung erfolgt asynchron bezüglich des Mode-Requesters; die RTE garantiert atomare Zustandswechsel über alle gebundenen Partitionen/Cores.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR-Versionsbruch (R3.x vs. R4.x):</strong></li>\n<li>In <strong>R3.x</strong> sind Modusdeklarationen direkt in <code>SenderReceiverInterface</code> eingebettet.</li>\n<li>Ab <strong>AUTOSAR 4.x</strong> ist dieses Pattern obsolet; Moduskommunikation erfordert zwingend das dedizierte <code>ModeSwitchInterface</code> mit <code>ModeDeclarationGroupPrototype</code> (Trennung von S/R-Datenübertragung und Mode-Switching).</li>\n<li><strong>RTE-API-Vertrag (C-Code-Generierung):</strong></li>\n<li>Modusabfrage generiert typischerweise: <code>Rte_Mode_&lt;port&gt;_&lt;modeGroup&gt;()</code> (z. B. <code>Rte_Mode_currentMode_currentMode(&amp;mode)</code> bzw. Rückgabe des Enum-Typs <code>Rte_ModeType_ECUMMode</code>).</li>\n<li><strong>Konfigurationsvorgaben:</strong></li>\n<li>Mapping des Ports im Service-Component-Descriptor des EcuM (<code>EcuM_CurrentMode</code>).</li>\n<li>Verbindung im Composition-Descriptor: 1:n-Verbindung (<code>AssemblyConnector</code>) vom EcuM-P-Port zu beliebig vielen SWC-R-Ports ohne Bus-Übertragung (reine ECU-interne VFB-Kommunikation).</li>\n</ul>"}, {"id": "FIG-bc387c3e1e02d090", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Strukturdiagramm / Metamodell-Instanzdarstellung einer VFB-Schnittstellendeklaration (Interface Specification).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Virtual Function Bus (VFB), Versionsstand R3.0.7 / R3.1.5 (Kapitel 8: <em>Mode Management</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Definition der Schnittstelle zur Entkopplung von Mode-Manager-Komponenten (hier dem <code>EcuM</code> – ECU State Manager) und applikativen Software-Komponenten (SWCs). Dient der standardisierten Propagierung von Systemzuständen (z. B. <code>STARTUP</code>, <code>RUN</code>, <code>POST_RUN</code>, <code>SLEEP</code>, <code>SHUTDOWN</code>) über den VFB bzw. die RTE an abhängige SWC-Runnables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Entität:</strong> <code>EcuMCurrentMode</code></li>\n<li><strong>Stereotyp:</strong> <code>&lt;&lt;SenderReceiverInterface&gt;&gt;</code> (Spezifikationsstandard in AUTOSAR R3.x für modale Kommunikation vor Einführung dedizierter <code>ModeSwitchInterfaces</code>).</li>\n<li><strong>Attribute / Enthaltene Elemente:</strong></li>\n<li><strong>Sektion:</strong> <code>ModeDeclarationGroups:</code></li>\n<li><strong>Element:</strong> <code>currentMode</code> als Instanz bzw. Mode-Prototyp der Modusgruppe.</li>\n<li><strong>Typisierung:</strong> <code>ECUMMode</code> (definiert die zulässige Menge diskreter Zustände/Modes als <code>ModeDeclarationGroup</code>).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Ein <code>SenderReceiverInterface</code> aggregiert in R3.x $0..<em>$ <code>ModeDeclarationGroup</code>-Referenzen parallel oder alternativ zu $0..</em>$ <code>DataElements</code>. Im vorliegenden Beispiel besteht eine 1:1-Bindung (<code>ECUMMode currentMode</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um eine statische Metamodell-Deklaration handelt, greift die daraus resultierende Laufzeitsemantik auf dem VFB:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Sender/Mode Manager:</strong> Der <code>EcuM</code> stellt einen P-Port bereit, der das Interface <code>EcuMCurrentMode</code> typisiert. Bei internem Zustandsübergang wird die Modusänderung an die RTE übergeben.</li>\n<li><strong>Receiver/Mode User:</strong> Applikative SWCs binden über R-Ports an dieses Interface.</li>\n<li><strong>RTE-Ablaufsteuerung:</strong></li>\n<li><strong>Moduswechsel (Mode Transition):</strong> Der Übergang triggert RTE-seitig configurierte <code>ModeSwitchEvents</code>.</li>\n<li><strong>Runnable-Steuerung:</strong> Aktivierung von Transitions-Runnables (<code>on-entry</code>, <code>on-exit</code>) oder bedingte Ausführung periodischer Runnables abhängig vom aktiven Modus.</li>\n<li><strong>Synchronisation:</strong> Ausführung erfolgt asynchron bezüglich des Mode-Requesters; die RTE garantiert atomare Zustandswechsel über alle gebundenen Partitionen/Cores.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR-Versionsbruch (R3.x vs. R4.x):</strong></li>\n<li>In <strong>R3.x</strong> sind Modusdeklarationen direkt in <code>SenderReceiverInterface</code> eingebettet.</li>\n<li>Ab <strong>AUTOSAR 4.x</strong> ist dieses Pattern obsolet; Moduskommunikation erfordert zwingend das dedizierte <code>ModeSwitchInterface</code> mit <code>ModeDeclarationGroupPrototype</code> (Trennung von S/R-Datenübertragung und Mode-Switching).</li>\n<li><strong>RTE-API-Vertrag (C-Code-Generierung):</strong></li>\n<li>Modusabfrage generiert typischerweise: <code>Rte_Mode_&lt;port&gt;_&lt;modeGroup&gt;()</code> (z. B. <code>Rte_Mode_currentMode_currentMode(&amp;mode)</code> bzw. Rückgabe des Enum-Typs <code>Rte_ModeType_ECUMMode</code>).</li>\n<li><strong>Konfigurationsvorgaben:</strong></li>\n<li>Mapping des Ports im Service-Component-Descriptor des EcuM (<code>EcuM_CurrentMode</code>).</li>\n<li>Verbindung im Composition-Descriptor: 1:n-Verbindung (<code>AssemblyConnector</code>) vom EcuM-P-Port zu beliebig vielen SWC-R-Ports ohne Bus-Übertragung (reine ECU-interne VFB-Kommunikation).</li>\n</ul>"}, {"id": "FIG-6b7b100932c2e420", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Strukturdiagramm / Metamodell-Instanzdarstellung einer VFB-Schnittstellendeklaration (Interface Specification).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Virtual Function Bus (VFB), Versionsstand R4.0.3 (Kapitel <em>Mode Management</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Definition eines dedizierten Modus-Umschaltschnittstellentyps zur Entkopplung von Mode-Manager-Komponenten (hier dem <code>EcuM</code> – ECU State Manager) und applikativen Software-Komponenten (SWCs). Dient der standardisierten Propagierung und Umschaltung von Systemzuständen (z. B. <code>STARTUP</code>, <code>RUN</code>, <code>POST_RUN</code>, <code>SLEEP</code>, <code>SHUTDOWN</code>) über den VFB bzw. die RTE an abhängige SWC-Runnables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Entität:</strong> <code>EcuMCurrentMode</code></li>\n<li><strong>Stereotyp:</strong> <code>&lt;&lt;ModeSwitchInterface&gt;&gt;</code> (AUTOSAR-4-Standard für modale Interaktion getrennt von Sender-Receiver-Datenströmen).</li>\n<li><strong>Attribute / Enthaltene Elemente:</strong></li>\n<li><strong>Sektion:</strong> <code>ModeDeclarationGroups</code></li>\n<li><strong>Element:</strong> <code>currentMode</code> als Instanz bzw. Mode-Declaration-Group-Prototype.</li>\n<li><strong>Typisierung:</strong> <code>ECUMMode</code> (definiert die zulässige Menge diskreter Zustände/Modes als <code>ModeDeclarationGroup</code>).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Ein <code>ModeSwitchInterface</code> deklariert Mode-Declaration-Group-Prototypen zur Modusübertragung. Im vorliegenden Beispiel besteht eine 1:1-Zuordnung (<code>ECUMMode currentMode</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um eine statische Metamodell-Deklaration handelt, greift die daraus resultierende Laufzeitsemantik auf dem VFB:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Sender/Mode Manager:</strong> Der <code>EcuM</code> stellt einen P-Port bereit, der das Interface <code>EcuMCurrentMode</code> typisiert. Bei internem Zustandsübergang wird die Modusänderung an die RTE übergeben.</li>\n<li><strong>Receiver/Mode User:</strong> Applikative SWCs binden über R-Ports an dieses Interface.</li>\n<li><strong>RTE-Ablaufsteuerung:</strong></li>\n<li><strong>Moduswechsel (Mode Transition):</strong> Der Übergang triggert RTE-seitig configurierte <code>ModeSwitchEvents</code>.</li>\n<li><strong>Runnable-Steuerung:</strong> Aktivierung von Transitions-Runnables (<code>on-entry</code>, <code>on-exit</code>) oder bedingte Ausführung periodischer Runnables abhängig vom aktiven Modus.</li>\n<li><strong>Synchronisation:</strong> Ausführung erfolgt asynchron bezüglich des Mode-Requesters; die RTE garantiert atomare Zustandswechsel über alle gebundenen Partitionen/Cores.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR-Architekturkonformität:</strong></li>\n<li>Moduskommunikation erfolgt über das dedizierte <code>ModeSwitchInterface</code> mit <code>ModeDeclarationGroupPrototype</code> (vollständige Trennung von S/R-Datenübertragung und Mode-Switching).</li>\n<li><strong>RTE-API-Vertrag (C-Code-Generierung):</strong></li>\n<li>Modusabfrage bzw. Modusumschaltung generiert standardisierte RTE-APIs (z. B. <code>Rte_Mode_&lt;port&gt;_&lt;modeGroup&gt;()</code> oder <code>Rte_Switch_&lt;port&gt;_&lt;modeGroup&gt;()</code>).</li>\n<li><strong>Konfigurationsvorgaben:</strong></li>\n<li>Mapping des Ports im Service-Component-Descriptor des EcuM (<code>EcuM_CurrentMode</code>).</li>\n<li>Verbindung im Composition-Descriptor: 1:n-Verbindung (<code>AssemblyConnector</code>) vom EcuM-P-Port zu SWC-R-Ports für ecu-interne Modussignalisierung.</li>\n</ul>"}, {"id": "FIG-ec0ffc964838292a", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Strukturdiagramm / Metamodell-Instanzdarstellung einer VFB-Schnittstellendeklaration (Interface Specification).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Virtual Function Bus (VFB), Versionsstand R4.0.3 (Kapitel <em>Mode Management</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Definition eines dedizierten Modus-Umschaltschnittstellentyps zur Entkopplung von Mode-Manager-Komponenten (hier dem <code>EcuM</code> – ECU State Manager) und applikativen Software-Komponenten (SWCs). Dient der standardisierten Propagierung und Umschaltung von Systemzuständen (z. B. <code>STARTUP</code>, <code>RUN</code>, <code>POST_RUN</code>, <code>SLEEP</code>, <code>SHUTDOWN</code>) über den VFB bzw. die RTE an abhängige SWC-Runnables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Entität:</strong> <code>EcuMCurrentMode</code></li>\n<li><strong>Stereotyp:</strong> <code>&lt;&lt;ModeSwitchInterface&gt;&gt;</code> (AUTOSAR-4-Standard für modale Interaktion getrennt von Sender-Receiver-Datenströmen).</li>\n<li><strong>Attribute / Enthaltene Elemente:</strong></li>\n<li><strong>Sektion:</strong> <code>ModeDeclarationGroups</code></li>\n<li><strong>Element:</strong> <code>currentMode</code> als Instanz bzw. Mode-Declaration-Group-Prototype.</li>\n<li><strong>Typisierung:</strong> <code>ECUMMode</code> (definiert die zulässige Menge diskreter Zustände/Modes als <code>ModeDeclarationGroup</code>).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Ein <code>ModeSwitchInterface</code> deklariert Mode-Declaration-Group-Prototypen zur Modusübertragung. Im vorliegenden Beispiel besteht eine 1:1-Zuordnung (<code>ECUMMode currentMode</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um eine statische Metamodell-Deklaration handelt, greift die daraus resultierende Laufzeitsemantik auf dem VFB:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Sender/Mode Manager:</strong> Der <code>EcuM</code> stellt einen P-Port bereit, der das Interface <code>EcuMCurrentMode</code> typisiert. Bei internem Zustandsübergang wird die Modusänderung an die RTE übergeben.</li>\n<li><strong>Receiver/Mode User:</strong> Applikative SWCs binden über R-Ports an dieses Interface.</li>\n<li><strong>RTE-Ablaufsteuerung:</strong></li>\n<li><strong>Moduswechsel (Mode Transition):</strong> Der Übergang triggert RTE-seitig configurierte <code>ModeSwitchEvents</code>.</li>\n<li><strong>Runnable-Steuerung:</strong> Aktivierung von Transitions-Runnables (<code>on-entry</code>, <code>on-exit</code>) oder bedingte Ausführung periodischer Runnables abhängig vom aktiven Modus.</li>\n<li><strong>Synchronisation:</strong> Ausführung erfolgt asynchron bezüglich des Mode-Requesters; die RTE garantiert atomare Zustandswechsel über alle gebundenen Partitionen/Cores.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR-Architekturkonformität:</strong></li>\n<li>Moduskommunikation erfolgt über das dedizierte <code>ModeSwitchInterface</code> mit <code>ModeDeclarationGroupPrototype</code> (vollständige Trennung von S/R-Datenübertragung und Mode-Switching).</li>\n<li><strong>RTE-API-Vertrag (C-Code-Generierung):</strong></li>\n<li>Modusabfrage bzw. Modusumschaltung generiert standardisierte RTE-APIs (z. B. <code>Rte_Mode_&lt;port&gt;_&lt;modeGroup&gt;()</code> oder <code>Rte_Switch_&lt;port&gt;_&lt;modeGroup&gt;()</code>).</li>\n<li><strong>Konfigurationsvorgaben:</strong></li>\n<li>Mapping des Ports im Service-Component-Descriptor des EcuM (<code>EcuM_CurrentMode</code>).</li>\n<li>Verbindung im Composition-Descriptor: 1:n-Verbindung (<code>AssemblyConnector</code>) vom EcuM-P-Port zu SWC-R-Ports für ecu-interne Modussignalisierung.</li>\n</ul>"}, {"id": "FIG-e6e1b32586ef3d94", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Strukturdiagramm / Metamodell-Instanzdarstellung einer VFB-Schnittstellendeklaration (Interface Specification).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Virtual Function Bus (VFB), Versionsstand R4.0.3 (Kapitel <em>Mode Management</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Definition eines dedizierten Modus-Umschaltschnittstellentyps zur Entkopplung von Mode-Manager-Komponenten (hier dem <code>EcuM</code> – ECU State Manager) und applikativen Software-Komponenten (SWCs). Dient der standardisierten Propagierung und Umschaltung von Systemzuständen (z. B. <code>STARTUP</code>, <code>RUN</code>, <code>POST_RUN</code>, <code>SLEEP</code>, <code>SHUTDOWN</code>) über den VFB bzw. die RTE an abhängige SWC-Runnables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Entität:</strong> <code>EcuMCurrentMode</code></li>\n<li><strong>Stereotyp:</strong> <code>&lt;&lt;ModeSwitchInterface&gt;&gt;</code> (AUTOSAR-4-Standard für modale Interaktion getrennt von Sender-Receiver-Datenströmen).</li>\n<li><strong>Attribute / Enthaltene Elemente:</strong></li>\n<li><strong>Sektion:</strong> <code>ModeDeclarationGroups</code></li>\n<li><strong>Element:</strong> <code>currentMode</code> als Instanz bzw. Mode-Declaration-Group-Prototype.</li>\n<li><strong>Typisierung:</strong> <code>ECUMMode</code> (definiert die zulässige Menge diskreter Zustände/Modes als <code>ModeDeclarationGroup</code>).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Ein <code>ModeSwitchInterface</code> deklariert Mode-Declaration-Group-Prototypen zur Modusübertragung. Im vorliegenden Beispiel besteht eine 1:1-Zuordnung (<code>ECUMMode currentMode</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um eine statische Metamodell-Deklaration handelt, greift die daraus resultierende Laufzeitsemantik auf dem VFB:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Sender/Mode Manager:</strong> Der <code>EcuM</code> stellt einen P-Port bereit, der das Interface <code>EcuMCurrentMode</code> typisiert. Bei internem Zustandsübergang wird die Modusänderung an die RTE übergeben.</li>\n<li><strong>Receiver/Mode User:</strong> Applikative SWCs binden über R-Ports an dieses Interface.</li>\n<li><strong>RTE-Ablaufsteuerung:</strong></li>\n<li><strong>Moduswechsel (Mode Transition):</strong> Der Übergang triggert RTE-seitig configurierte <code>ModeSwitchEvents</code>.</li>\n<li><strong>Runnable-Steuerung:</strong> Aktivierung von Transitions-Runnables (<code>on-entry</code>, <code>on-exit</code>) oder bedingte Ausführung periodischer Runnables abhängig vom aktiven Modus.</li>\n<li><strong>Synchronisation:</strong> Ausführung erfolgt asynchron bezüglich des Mode-Requesters; die RTE garantiert atomare Zustandswechsel über alle gebundenen Partitionen/Cores.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR-Architekturkonformität:</strong></li>\n<li>Moduskommunikation erfolgt über das dedizierte <code>ModeSwitchInterface</code> mit <code>ModeDeclarationGroupPrototype</code> (vollständige Trennung von S/R-Datenübertragung und Mode-Switching).</li>\n<li><strong>RTE-API-Vertrag (C-Code-Generierung):</strong></li>\n<li>Modusabfrage bzw. Modusumschaltung generiert standardisierte RTE-APIs (z. B. <code>Rte_Mode_&lt;port&gt;_&lt;modeGroup&gt;()</code> oder <code>Rte_Switch_&lt;port&gt;_&lt;modeGroup&gt;()</code>).</li>\n<li><strong>Konfigurationsvorgaben:</strong></li>\n<li>Mapping des Ports im Service-Component-Descriptor des EcuM (<code>EcuM_CurrentMode</code>).</li>\n<li>Verbindung im Composition-Descriptor: 1:n-Verbindung (<code>AssemblyConnector</code>) vom EcuM-P-Port zu SWC-R-Ports für ecu-interne Modussignalisierung.</li>\n</ul>"}, {"id": "FIG-6e3036fd8c97273c", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Strukturdiagramm / Metamodell-Instanzdarstellung einer VFB-Schnittstellendeklaration (Interface Specification).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Virtual Function Bus (VFB), Versionsstand R4.0.3 (Kapitel <em>Mode Management</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Definition eines dedizierten Modus-Umschaltschnittstellentyps zur Entkopplung von Mode-Manager-Komponenten (hier dem <code>EcuM</code> – ECU State Manager) und applikativen Software-Komponenten (SWCs). Dient der standardisierten Propagierung und Umschaltung von Systemzuständen (z. B. <code>STARTUP</code>, <code>RUN</code>, <code>POST_RUN</code>, <code>SLEEP</code>, <code>SHUTDOWN</code>) über den VFB bzw. die RTE an abhängige SWC-Runnables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Entität:</strong> <code>EcuMCurrentMode</code></li>\n<li><strong>Stereotyp:</strong> <code>&lt;&lt;ModeSwitchInterface&gt;&gt;</code> (AUTOSAR-4-Standard für modale Interaktion getrennt von Sender-Receiver-Datenströmen).</li>\n<li><strong>Attribute / Enthaltene Elemente:</strong></li>\n<li><strong>Sektion:</strong> <code>ModeDeclarationGroups</code></li>\n<li><strong>Element:</strong> <code>currentMode</code> als Instanz bzw. Mode-Declaration-Group-Prototype.</li>\n<li><strong>Typisierung:</strong> <code>ECUMMode</code> (definiert die zulässige Menge diskreter Zustände/Modes als <code>ModeDeclarationGroup</code>).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Ein <code>ModeSwitchInterface</code> deklariert Mode-Declaration-Group-Prototypen zur Modusübertragung. Im vorliegenden Beispiel besteht eine 1:1-Zuordnung (<code>ECUMMode currentMode</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um eine statische Metamodell-Deklaration handelt, greift die daraus resultierende Laufzeitsemantik auf dem VFB:</em></p>\n<ul class=\"fig-list\">\n<li><strong>Sender/Mode Manager:</strong> Der <code>EcuM</code> stellt einen P-Port bereit, der das Interface <code>EcuMCurrentMode</code> typisiert. Bei internem Zustandsübergang wird die Modusänderung an die RTE übergeben.</li>\n<li><strong>Receiver/Mode User:</strong> Applikative SWCs binden über R-Ports an dieses Interface.</li>\n<li><strong>RTE-Ablaufsteuerung:</strong></li>\n<li><strong>Moduswechsel (Mode Transition):</strong> Der Übergang triggert RTE-seitig configurierte <code>ModeSwitchEvents</code>.</li>\n<li><strong>Runnable-Steuerung:</strong> Aktivierung von Transitions-Runnables (<code>on-entry</code>, <code>on-exit</code>) oder bedingte Ausführung periodischer Runnables abhängig vom aktiven Modus.</li>\n<li><strong>Synchronisation:</strong> Ausführung erfolgt asynchron bezüglich des Mode-Requesters; die RTE garantiert atomare Zustandswechsel über alle gebundenen Partitionen/Cores.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR-Architekturkonformität:</strong></li>\n<li>Moduskommunikation erfolgt über das dedizierte <code>ModeSwitchInterface</code> mit <code>ModeDeclarationGroupPrototype</code> (vollständige Trennung von S/R-Datenübertragung und Mode-Switching).</li>\n<li><strong>RTE-API-Vertrag (C-Code-Generierung):</strong></li>\n<li>Modusabfrage bzw. Modusumschaltung generiert standardisierte RTE-APIs (z. B. <code>Rte_Mode_&lt;port&gt;_&lt;modeGroup&gt;()</code> oder <code>Rte_Switch_&lt;port&gt;_&lt;modeGroup&gt;()</code>).</li>\n<li><strong>Konfigurationsvorgaben:</strong></li>\n<li>Mapping des Ports im Service-Component-Descriptor des EcuM (<code>EcuM_CurrentMode</code>).</li>\n<li>Verbindung im Composition-Descriptor: 1:n-Verbindung (<code>AssemblyConnector</code>) vom EcuM-P-Port zu SWC-R-Ports für ecu-interne Modussignalisierung.</li>\n</ul>"}], "trans": [{"from": "FIG-a6a64539d888e47e", "to": "FIG-bc387c3e1e02d090", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bc387c3e1e02d090", "to": "FIG-6b7b100932c2e420", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Schnittstellen-Stereotyp von <code>&lt;&lt;SenderReceiverInterface&gt;&gt;</code> auf <code>&lt;&lt;ModeSwitchInterface&gt;&gt;</code> geändert.</li>\n<li>Doppelpunkt nach der Sektionsüberschrift <code>ModeDeclarationGroups:</code> entfernt (<code>ModeDeclarationGroups</code>).</li>\n<li>Typ- und Rollenbezeichnung von <code>ECUMMode currentMode</code> typografisch leicht versetzt (<code>ModeDeclarationGroups</code> ohne Doppelpunkt).</li>\n</ul>"}, {"from": "FIG-6b7b100932c2e420", "to": "FIG-ec0ffc964838292a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ec0ffc964838292a", "to": "FIG-e6e1b32586ef3d94", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e6e1b32586ef3d94", "to": "FIG-6e3036fd8c97273c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
